147	// CreateSplitIntent 由当前持有人登记一份藏品拆分意向：指定唯一意向编号、
148	// 藏品、期望持有人与版本、绝对到期时间，以及至少两个账户和各自份额
149	// （万分之一，每份 1..10000，合计必须为 10000，账户不能重复）。发起人与
150	// 参与账户都须已登记且可用；发起人可以列入方案，其份额在创建时视为已
151	// 同意。系列封存不妨碍登记意向；藏品已有仍有效的待确认或已达成意向时，
152	// 新建按状态冲突拒绝。意向只保存未来拆分的约定，不改变持有与版税应付。
153	//
154	// 请求号与发行、转让等操作共用同一操作者的请求号范围：相同业务参数
155	// （份额名单仅排列不同视为相同）重提返回首次结果，参数不同返回
156	// ErrRequestConflict；参数错误与引用不存在不占用请求号。
157	func (r *Registry) CreateSplitIntent(req CreateSplitIntentRequest) (CreateSplitIntentResult, error) {
158		if err := req.validatePresent(); err != nil {
159			return CreateSplitIntentResult{}, err
160		}
161		// 方案的形状校验（账户数量、重复、份额范围、合计）不依赖状态，在取锁
162		// 前完成；不合法时不占用请求号。
163		shares, err := normalizeSplitShares(req.Shares)
164		if err != nil {
165			return CreateSplitIntentResult{IntentID: req.IntentID, Err: err}, err
166		}
167		r.mu.Lock()
168		defer r.mu.Unlock()
169		if err := r.checkOpen(); err != nil {
170			return CreateSplitIntentResult{}, err
171		}
172	
173		now := r.now()
174		key := requestKey(req.Operator, req.RequestID)
175		sig := createIntentParamsSig(req, shares)
176		if prev, ok := r.state.Requests[key]; ok {
177			return r.replayCreateIntent(prev, sig)
178		}
179	
180		if bizErr := r.checkCreateSplitIntent(req, shares, now); bizErr != nil {
181			if !isValidationErr(bizErr) {
182				// 状态类业务拒绝（编号占用、停用、持有版本不符、状态冲突等）
183				// 占用请求号并落盘；参数错误与引用不存在不占用。
184				r.state.Requests[key] = request{
185					Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_create",
186					Params: sig, Rejected: true, Reason: errCode(bizErr),
187					IntentID: req.IntentID, ItemID: req.ItemID,
188				}
189				_ = r.commit()
190			}
191			return CreateSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
192		}
193	
194		h := r.state.Holdings[req.ItemID]
195		// 发起人列入方案时，其份额在创建时视为已同意。
196		for i := range shares {
197			if shares[i].AccountID == req.Operator {
198				shares[i].Answer = SplitAnswerAgree
199			}
200		}
201		rec := intentRec{
202			ID: req.IntentID, ItemID: req.ItemID, InitiatorID: req.Operator,
203			Shares: shares, GrantVer: h.Version, ExpiresAt: req.ExpiresAt,
204			CreatedAt: now,
205		}
206		r.state.Intents[req.IntentID] = rec
207		status := r.intentCurrentStatus(rec, now)
208		seq := r.state.NextIntentSeq + 1
209		r.state.NextIntentSeq = seq
210		r.state.IntentEvents = append(r.state.IntentEvents, intentEvent{
211			Seq: seq, IntentID: req.IntentID, ItemID: req.ItemID, Kind: "create",
212			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
213			FromStatus: "", ToStatus: status, OccurredAt: now,
214		})
215		r.state.Requests[key] = request{
216			Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_create",
217			Params: sig, IntentID: req.IntentID, ItemID: req.ItemID,
218			Version: h.Version, Status: status,
219		}
220		if err := r.commit(); err != nil {
221			return CreateSplitIntentResult{}, err
222		}
223		return CreateSplitIntentResult{IntentID: req.IntentID, Status: status, GrantVer: h.Version}, nil
224	}
225	
226	func (r *Registry) checkCreateSplitIntent(req CreateSplitIntentRequest, shares []intentShare, now time.Time) error {
227		h, ok := r.state.Holdings[req.ItemID]
228		if !ok {
229			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
230				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
231			}
232			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
233		}
234		op, ok := r.state.Accounts[req.Operator]
235		if !ok {
236			return fmt.Errorf("%w: 发起人账户 %s", ErrNotFound, req.Operator)
237		}
238		for _, sh := range shares {
239			if _, ok := r.state.Accounts[sh.AccountID]; !ok {
240				return fmt.Errorf("%w: 参与账户 %s", ErrNotFound, sh.AccountID)
241			}
242		}
243		if !op.Active {
244			return fmt.Errorf("%w: 发起人账户 %s", ErrAccountInactive, req.Operator)
245		}
246		for _, sh := range shares {
247			if !r.state.Accounts[sh.AccountID].Active {
248				return fmt.Errorf("%w: 参与账户 %s", ErrAccountInactive, sh.AccountID)
249			}
250		}
251		// 意向编号占用是对象级冲突，优先于当前时间与持有版本检查。
252		if _, exists := r.state.Intents[req.IntentID]; exists {
253			return fmt.Errorf("%w: 意向编号 %s 已被占用", ErrAlreadyExists, req.IntentID)
254		}
255		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不再有效。
256		if !req.ExpiresAt.After(now) {
257			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
258				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
259		}
260		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
261			req.Operator != h.OwnerID {
262			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
263				ErrConflict, req.ItemID, h.OwnerID, h.Version)
264		}
265		// 同一藏品已有仍有效的待确认或已达成意向时，新建按状态冲突拒绝；
266		// 已拒绝、已撤回、已失效或已过期的意向不妨碍另建方案。
267		for _, other := range r.state.Intents {
268			if other.ItemID != req.ItemID {
269				continue
270			}
271			switch r.intentCurrentStatus(other, now) {
272			case SplitPending, SplitAgreed:
273				return fmt.Errorf("%w: 藏品 %s 已有仍有效的拆分意向 %s",
274					ErrConflict, req.ItemID, other.ID)
275			}
276		}
277		return nil
278	}
