280	func (r *Registry) replayCreateIntent(prev request, sig string) (CreateSplitIntentResult, error) {
281		if prev.Kind != "intent_create" || prev.Params != sig {
282			return CreateSplitIntentResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
283				ErrRequestConflict, prev.Operator, prev.RequestID)
284		}
285		res := CreateSplitIntentResult{IntentID: prev.IntentID, Status: prev.Status,
286			GrantVer: prev.Version, Replayed: true}
287		if prev.Rejected {
288			res.Err = codeErr(prev.Reason)
289			res.Status = ""
290			res.GrantVer = 0
291			return res, res.Err
292		}
293		return res, nil
294	}
295	
296	func answerIntentParamsSig(req AnswerSplitIntentRequest) string {
297		b, _ := json.Marshal(struct {
298			Kind     string `json:"kind"`
299			IntentID string `json:"intent_id"`
300			Agree    bool   `json:"agree"`
301			Reason   string `json:"reason"`
302		}{"intent_answer", req.IntentID, req.Agree, req.Reason})
303		return string(b)
304	}
305	
306	// AnswerSplitIntent 由方案中的参与账户答复自己的份额（同意或拒绝）。
307	// 意向待确认或已达成且仍有效时才能答复：全部同意则意向显示已达成，
308	// 任一拒绝则显示已拒绝。重复相同答复成功但不新增记录；已答复后改答
309	// 拒绝（ErrSplitAnswered）。名单外账户无权答复（ErrForbidden）；已拒绝、
310	// 已撤回、已失效或已过期的意向不再接受答复，分别明确拒绝。发起人列入
311	// 方案时创建即视为已同意，再作不同答复按改答拒绝。
312	//
313	// 请求号语义与其他操作一致：相同参数重提回放首次结果，参数不同返回
314	// ErrRequestConflict；参数错误与引用不存在不占用请求号。
315	func (r *Registry) AnswerSplitIntent(req AnswerSplitIntentRequest) (AnswerSplitIntentResult, error) {
316		missing := []string{}
317		if strings.TrimSpace(req.Operator) == "" {
318			missing = append(missing, "operator")
319		}
320		if strings.TrimSpace(req.Reason) == "" {
321			missing = append(missing, "reason")
322		}
323		if strings.TrimSpace(req.RequestID) == "" {
324			missing = append(missing, "request_id")
325		}
326		if strings.TrimSpace(req.IntentID) == "" {
327			missing = append(missing, "intent_id")
328		}
329		if len(missing) > 0 {
330			return AnswerSplitIntentResult{}, fmt.Errorf("%w: 答复拆分意向请求缺少必填字段 %s",
331				ErrInvalidArgument, strings.Join(missing, ", "))
332		}
333		r.mu.Lock()
334		defer r.mu.Unlock()
335		if err := r.checkOpen(); err != nil {
336			return AnswerSplitIntentResult{}, err
337		}
338	
339		now := r.now()
340		key := requestKey(req.Operator, req.RequestID)
341		sig := answerIntentParamsSig(req)
342		if prev, ok := r.state.Requests[key]; ok {
343			return r.replayAnswerIntent(prev, sig)
344		}
345	
346		rec, ok := r.state.Intents[req.IntentID]
347		if !ok {
348			// 引用不存在不占用请求号。
349			err := fmt.Errorf("%w: 拆分意向 %s", ErrNotFound, req.IntentID)
350			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: err}, err
351		}
352		idx := -1
353		for i, sh := range rec.Shares {
354			if sh.AccountID == req.Operator {
355				idx = i
356				break
357			}
358		}
359		if idx < 0 {
360			bizErr := fmt.Errorf("%w: 账户 %s 不在意向 %s 的分配方案中",
361				ErrForbidden, req.Operator, req.IntentID)
362			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_answer", req.IntentID, bizErr)
363			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
364		}
365		answer := SplitAnswerReject
366		if req.Agree {
367			answer = SplitAnswerAgree
368		}
369		// 已终结、已失效或已过期的意向不再接受答复，分别说明原因。
370		switch status := r.intentCurrentStatus(rec, now); status {
371		case SplitRejected, SplitWithdrawn, SplitInvalid, SplitExpired:
372			bizErr := intentEndedErr(status, req.IntentID)
373			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_answer", req.IntentID, bizErr)
374			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
375		}
376		if prev := rec.Shares[idx].Answer; prev != "" {
377			if prev == answer {
378				// 重复相同答复：成功但不新增变更记录；该请求号仍登记为成功，
379				// 相同请求重放回放同一结果。
380				status := r.intentCurrentStatus(rec, now)
381				r.state.Requests[key] = request{
382					Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_answer",
383					Params: sig, IntentID: req.IntentID, Status: status,
384				}
385				if err := r.commit(); err != nil {
386					return AnswerSplitIntentResult{}, err
387				}
388				return AnswerSplitIntentResult{IntentID: req.IntentID, Status: status}, nil
389			}
390			// 已答复后改答拒绝。
391			bizErr := fmt.Errorf("%w: 账户 %s 已答复 %s，不能改为 %s",
392				ErrSplitAnswered, req.Operator, prev, answer)
393			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_answer", req.IntentID, bizErr)
394			return AnswerSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
395		}
396	
397		from := r.intentCurrentStatus(rec, now)
398		rec.Shares[idx].Answer = answer
399		if answer == SplitAnswerReject {
400			// 任一参与账户拒绝即终结为已拒绝（落盘终态）。
401			rec.Status = "rejected"
402			rec.EndedAt = now
403		}
404		r.state.Intents[req.IntentID] = rec
405		to := r.intentCurrentStatus(rec, now)
406		seq := r.state.NextIntentSeq + 1
407		r.state.NextIntentSeq = seq
408		r.state.IntentEvents = append(r.state.IntentEvents, intentEvent{
409			Seq: seq, IntentID: req.IntentID, ItemID: rec.ItemID, Kind: "answer",
410			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
411			Answer: answer, FromStatus: from, ToStatus: to, OccurredAt: now,
412		})
413		r.state.Requests[key] = request{
414			Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_answer",
415			Params: sig, IntentID: req.IntentID, Status: to,
416		}
417		if err := r.commit(); err != nil {
418			return AnswerSplitIntentResult{}, err
419		}
420		return AnswerSplitIntentResult{IntentID: req.IntentID, Status: to}, nil
421	}
422	
423	// intentEndedErr 构造意向已终结、失效或过期时的拒绝原因。
424	func intentEndedErr(status, intentID string) error {
425		switch status {
426		case SplitRejected:
427			return fmt.Errorf("%w: 拆分意向 %s 已拒绝，不再接受答复或撤回", ErrSplitIntentRejected, intentID)
428		case SplitWithdrawn:
429			return fmt.Errorf("%w: 拆分意向 %s 已撤回，不再接受答复", ErrSplitIntentWithdrawn, intentID)
430		case SplitInvalid:
431			return fmt.Errorf("%w: 拆分意向 %s 已失效（持有版本变化或参与账户停用）", ErrSplitIntentInvalid, intentID)
432		default:
433			return fmt.Errorf("%w: 拆分意向 %s 已过期", ErrSplitIntentExpired, intentID)
434		}
435	}
436	
437	// recordIntentRequest 记录意向类操作的状态类业务拒绝并尽力落盘。
438	func (r *Registry) recordIntentRequest(key, sig, operator, requestID, kind, intentID string, bizErr error) {
439		r.state.Requests[key] = request{
440			Operator: operator, RequestID: requestID, Kind: kind,
441			Params: sig, Rejected: true, Reason: errCode(bizErr), IntentID: intentID,
442		}
443		_ = r.commit()
444	}
445	
446	func (r *Registry) replayAnswerIntent(prev request, sig string) (AnswerSplitIntentResult, error) {
447		if prev.Kind != "intent_answer" || prev.Params != sig {
448			return AnswerSplitIntentResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
449				ErrRequestConflict, prev.Operator, prev.RequestID)
450		}
451		res := AnswerSplitIntentResult{IntentID: prev.IntentID, Status: prev.Status, Replayed: true}
452		if prev.Rejected {
453			res.Err = codeErr(prev.Reason)
454			res.Status = ""
455			return res, res.Err
456		}
457		return res, nil
458	}
459	
460	func withdrawIntentParamsSig(req WithdrawSplitIntentRequest) string {
461		b, _ := json.Marshal(struct {
462			Kind     string `json:"kind"`
463			IntentID string `json:"intent_id"`
464			Reason   string `json:"reason"`
465		}{"intent_withdraw", req.IntentID, req.Reason})
466		return string(b)
467	}
468	
469	// WithdrawSplitIntent 由发起人撤回仍有效的待确认或已达成意向。仅发起人
470	// 可撤回（ErrForbidden）；已拒绝的意向不能撤回（ErrSplitIntentRejected），
471	// 已失效或已过期的意向拒绝撤回并说明原因；已撤回后再次撤回成功但不新增
472	// 记录（幂等）。请求号语义与其他操作一致。
473	func (r *Registry) WithdrawSplitIntent(req WithdrawSplitIntentRequest) (WithdrawSplitIntentResult, error) {
474		missing := []string{}
475		if strings.TrimSpace(req.Operator) == "" {
476			missing = append(missing, "operator")
477		}
478		if strings.TrimSpace(req.Reason) == "" {
479			missing = append(missing, "reason")
480		}
481		if strings.TrimSpace(req.RequestID) == "" {
482			missing = append(missing, "request_id")
483		}
484		if strings.TrimSpace(req.IntentID) == "" {
485			missing = append(missing, "intent_id")
486		}
487		if len(missing) > 0 {
488			return WithdrawSplitIntentResult{}, fmt.Errorf("%w: 撤回拆分意向请求缺少必填字段 %s",
489				ErrInvalidArgument, strings.Join(missing, ", "))
490		}
491		r.mu.Lock()
492		defer r.mu.Unlock()
493		if err := r.checkOpen(); err != nil {
494			return WithdrawSplitIntentResult{}, err
495		}
496	
497		now := r.now()
498		key := requestKey(req.Operator, req.RequestID)
499		sig := withdrawIntentParamsSig(req)
500		if prev, ok := r.state.Requests[key]; ok {
501			return r.replayWithdrawIntent(prev, sig)
502		}
503	
504		rec, ok := r.state.Intents[req.IntentID]
505		if !ok {
506			// 引用不存在不占用请求号。
507			err := fmt.Errorf("%w: 拆分意向 %s", ErrNotFound, req.IntentID)
508			return WithdrawSplitIntentResult{IntentID: req.IntentID, Err: err}, err
509		}
510		if rec.InitiatorID != req.Operator {
511			bizErr := fmt.Errorf("%w: 只有发起人 %s 可以撤回意向 %s",
512				ErrForbidden, rec.InitiatorID, req.IntentID)
513			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_withdraw", req.IntentID, bizErr)
514			return WithdrawSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
515		}
516		status := r.intentCurrentStatus(rec, now)
517		switch status {
518		case SplitWithdrawn:
519			// 已撤回是幂等终态：不新增变更记录；该请求号仍登记为成功。
520			r.state.Requests[key] = request{
521				Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_withdraw",
522				Params: sig, IntentID: req.IntentID, Status: SplitWithdrawn,
523			}
524			if err := r.commit(); err != nil {
525				return WithdrawSplitIntentResult{}, err
526			}
527			return WithdrawSplitIntentResult{IntentID: req.IntentID, Status: SplitWithdrawn}, nil
528		case SplitRejected, SplitInvalid, SplitExpired:
529			bizErr := intentEndedErr(status, req.IntentID)
530			r.recordIntentRequest(key, sig, req.Operator, req.RequestID, "intent_withdraw", req.IntentID, bizErr)
531			return WithdrawSplitIntentResult{IntentID: req.IntentID, Err: bizErr}, bizErr
532		}
533	
534		rec.Status = "withdrawn"
535		rec.EndedAt = now
536		r.state.Intents[req.IntentID] = rec
537		seq := r.state.NextIntentSeq + 1
538		r.state.NextIntentSeq = seq
539		r.state.IntentEvents = append(r.state.IntentEvents, intentEvent{
540			Seq: seq, IntentID: req.IntentID, ItemID: rec.ItemID, Kind: "withdraw",
541			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
542			FromStatus: status, ToStatus: SplitWithdrawn, OccurredAt: now,
543		})
544		r.state.Requests[key] = request{
545			Operator: req.Operator, RequestID: req.RequestID, Kind: "intent_withdraw",
546			Params: sig, IntentID: req.IntentID, Status: SplitWithdrawn,
547		}
548		if err := r.commit(); err != nil {
549			return WithdrawSplitIntentResult{}, err
550		}
551		return WithdrawSplitIntentResult{IntentID: req.IntentID, Status: SplitWithdrawn}, nil
552	}
553	
554	func (r *Registry) replayWithdrawIntent(prev request, sig string) (WithdrawSplitIntentResult, error) {
555		if prev.Kind != "intent_withdraw" || prev.Params != sig {
556			return WithdrawSplitIntentResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
557				ErrRequestConflict, prev.Operator, prev.RequestID)
558		}
559		res := WithdrawSplitIntentResult{IntentID: prev.IntentID, Status: prev.Status, Replayed: true}
560		if prev.Rejected {
561			res.Err = codeErr(prev.Reason)
562			res.Status = ""
563			return res, res.Err
564		}
565		return res, nil
566	}
567	
568	// ---- 拆分意向查询 ----
569	
570	// GetSplitIntent 按编号查询拆分意向的方案、各方答复与当前状态。意向不
571	// 存在时返回包裹 ErrNotFound 的错误；返回的 Status 按当前持有、账户
572	// 状态与时间实时计算（已失效、已过期为派生状态）。已结束的意向仍可
573	// 查询。
574	func (r *Registry) GetSplitIntent(intentID string) (SplitIntent, error) {
575		r.mu.Lock()
576		defer r.mu.Unlock()
577		if err := r.checkOpen(); err != nil {
578			return SplitIntent{}, err
579		}
580		rec, ok := r.state.Intents[intentID]
581		if !ok {
582			return SplitIntent{}, fmt.Errorf("%w: 拆分意向 %s", ErrNotFound, intentID)
583		}
584		parties := make([]SplitParty, 0, len(rec.Shares))
585		for _, sh := range rec.Shares {
586			parties = append(parties, SplitParty{
587				AccountID: sh.AccountID, Share: sh.Share, Answer: sh.Answer,
588			})
589		}
590		return SplitIntent{
591			ID: rec.ID, ItemID: rec.ItemID, InitiatorID: rec.InitiatorID,
592			Shares: parties, GrantVer: rec.GrantVer, ExpiresAt: rec.ExpiresAt,
593			Status:    r.intentCurrentStatus(rec, r.now()),
594			CreatedAt: rec.CreatedAt, EndedAt: rec.EndedAt,
595		}, nil
596	}
597	
598	// SplitIntentHistory 按藏品查看拆分意向变更记录（创建、首次答复、撤回），
599	// 按发生先后排列；每条记录包含意向编号、操作者、原因、请求号、发生时间
600	// 与前后状态。藏品不存在时返回包裹 ErrNotFound 的错误。
601	func (r *Registry) SplitIntentHistory(itemID string) ([]SplitIntentEvent, error) {
602		r.mu.Lock()
603		defer r.mu.Unlock()
604		if err := r.checkOpen(); err != nil {
605			return nil, err
606		}
607		if _, ok := r.state.Items[itemID]; !ok {
608			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
609		}
610		out := make([]SplitIntentEvent, 0)
611		for _, e := range r.state.IntentEvents {
612			if e.ItemID != itemID {
613				continue
614			}
615			out = append(out, SplitIntentEvent{
616				Seq: e.Seq, IntentID: e.IntentID, ItemID: e.ItemID, Kind: e.Kind,
617				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
618				Answer: e.Answer, FromStatus: e.FromStatus, ToStatus: e.ToStatus,
619				OccurredAt: e.OccurredAt,
620			})
621		}
622		return out, nil
623	}
624

